import subprocess

def check_service_status():
    try:
        # Check if the service is active
        result = subprocess.run(
            ["systemctl", "is-active", "alienware-vllm-strong-long.service"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        is_active = result.stdout.strip() == "active"
        return is_active, result.stdout.strip()
    except Exception as e:
        return False, str(e)

def get_last_logs():
    try:
        # Get the last 20 lines of the service log
        result = subprocess.run(
            ["journalctl", "-u", "alienware-vllm-strong-long.service", "-n", "20", "--no-pager"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        return result.stdout
    except Exception as e:
        return str(e)

# Step 1: Check status
is_active, status_msg = check_service_status()
print(f"Service Active: {is_active}")
print(f"Status Message: {status_msg}")

# Step 2: If not active, inspect logs
if not is_active:
    logs = get_last_logs()
    print("Last 20 Log Lines:")
    print(logs)
else:
    print("Service is active. No logs needed.")
